function Gear_3_InLvl1:__init()
    self.controller = nil
end


function Gear_3_InLvl1:__delete()
    self.co_1 = nil

    if not isNull(self.co_2) then 
        cs_coroutine.stop(self.co_2)
        self.co_2 = nil
    end
end



function Gear_3_InLvl1:Awake()
    KTool.SetActive(self.controller.gameObject, true)
end

function Gear_3_InLvl1:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.interrupter and self.questBH and self.params )
    self.quest = DreamSpaceLuaUtils.GetLuaScr(self.questBH.gameObject, "Game.DreamSpace.Level1.Quest.QuestLvl1" )
    self.taskRange = QuestUtils.ReadTaskRangeFromLuaParameters( self.params )
    assert( self.quest and self.taskRange )
    assert(self.taskRange:IsSetedInInspector())

    self.buttonElectricalTrigger = KTool.GetComponent(self.interrupter.gameObject, typeof(ElectricalTrigger)) -- ElectricalTrigger
    assert( self.buttonElectricalTrigger )

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(self.DelayInit, self)
end



function Gear_3_InLvl1:DelayInit() 

    while (isNull(self.quest.core)) or (self.quest.core.isInit == false) or (self.interrupter.isInit == false) do
        coroutine.yield(Yielders.EndOfFrame)
    end


    self.buttonElectricalTrigger:WhenBeTriggerdFromInit( '+', Bind(self, self.OnButtonFirstTriggered) )
    table.insert( self.quest.core.AfterTaskSwitchFuncs, Bind(self, self.OnAfterTaskSwitch) )
    

    self.taskRange:Init(self.quest.core)
    self.interrupter.isActive = self.quest.core:IsGearActive(self.taskRange)

    self.quest:RegistSwitchTaskFunc(self.taskRange, function(taskSwitchData_)
        return self:SwitchTask(taskSwitchData_)
    end)
end

    

function Gear_3_InLvl1:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    DreamSpaceLuaUtils.StopCoroutine( self.co_2 )
    self.co_1 = nil
    self.co_2 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --






-- 在 btn 被第一次按下时, 触发 task切换
function Gear_3_InLvl1:OnButtonFirstTriggered()
    assert( self.taskRange.isInit )

    DreamSpaceLuaUtils.StopCoroutine( self.co_2 )
    self.co_2 = cs_coroutine.start( function()
        self.quest:ToNextTask(self.taskRange)
    end)

end



function Gear_3_InLvl1:OnAfterTaskSwitch(taskSwitchData_)
    assert(self.taskRange.isInit)
    -- 进入新的 task 后, button 需要及时 激活/禁用
    self.interrupter.isActive = self.taskRange:IsInRange(taskSwitchData_.newTaskIdx)
end



function Gear_3_InLvl1:SwitchTask(taskSwitchData_)
    -- ------ 切换 ui texts 显示:
    local newTask = self.quest.core:GetTask(taskSwitchData_.newTaskIdx)
    assert( newTask ) 

